<script setup>
import { computed,onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import { api } from '../api'
const points=ref([]),selected=ref([]),count=ref(10),error=ref(''),busy=ref(false),router=useRouter();const enabled=computed(()=>points.value.filter(p=>p.enabled))
onMounted(async()=>{try{points.value=await api('/api/knowledge-points')}catch(e){error.value=e.message}})
async function create(){error.value='';if(!selected.value.length){error.value='请至少选择一个知识点';return}busy.value=true;try{const made=await api('/api/practices',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:{knowledgeIds:selected.value,questionCount:count.value}});router.push(`/practice/${made.id}`)}catch(e){error.value=e.activityId?`已有${e.kind==='PRACTICE'?'普通练习':'学习任务'}进行中（活动 ${e.activityId}），请先完成。`:e.message}finally{busy.value=false}}
</script>
<template><div class="practice-shell"><header class="practice-top"><div><span class="practice-kicker">M04 · PRACTICE</span><h1 class="practice-title">设置一次普通练习</h1></div><RouterLink to="/">返回首页</RouterLink></header><form class="p-card" @submit.prevent="create"><h2>选择知识点</h2><p class="p-muted">系统按选择顺序轮转出题；同一知识点题量不足时会重复取题。</p><div class="p-grid p-two"><label v-for="p in enabled" :key="p.id" class="p-option"><input v-model="selected" type="checkbox" :value="p.id"><span><strong>{{p.code}}</strong><br><small>{{p.name}}</small></span></label></div><label class="p-field">题目数量（1—20）<input v-model.number="count" type="number" min="1" max="20" required></label><p v-if="error" class="p-error" role="alert">{{error}}</p><div class="p-actions"><button class="p-primary" :disabled="busy">{{busy?'正在组卷…':'创建练习'}}</button><RouterLink to="/practice/history">查看历史</RouterLink></div></form></div></template>
